```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines = [];
rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    // 引数をパース
    let idx = 0;
    const iteration = parseInt(lines[idx++]);
    const total = parseInt(lines[idx++]);
    const prefix = lines[idx++] || 'Progress:';
    const suffix = lines[idx++] || '';
    const decimals = parseInt(lines[idx++]) || 1;
    const length = parseInt(lines[idx++]) || 50;
    const fill = lines[idx++] || '█';

    // 処理
    const percent = (100 * (iteration / total)).toFixed(decimals);
    const filledLength = Math.floor(length * iteration / total);
    const bar = fill.repeat(filledLength) + '-'.repeat(length - filledLength);
    let output = `\r${prefix} |${bar}| ${percent}% ${suffix}`;

    if (iteration === total) {
        output += '\n';
    }

    process.stdout.write(output);
});
```

