```javascript
const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

let inputLines = [];
rl.on('line', (line) => {
  inputLines.push(line);
});

rl.on('close', () => {
  let idx = 0;
  // nodes
  const nodes = parseInt(inputLines[idx++], 10);
  // time (optional)
  let time = null;
  if (idx < inputLines.length && inputLines[idx] !== '') {
    time = inputLines[idx];
  }
  idx++;
  // account (optional)
  let account = null;
  if (idx < inputLines.length && inputLines[idx] !== '') {
    account = inputLines[idx];
  }
  idx++;
  // options (optional dictionary)
  let options = null;
  if (idx < inputLines.length && inputLines[idx] !== '') {
    const dictStr = inputLines[idx];
    // parse Python dict like {'a': 1, 'b': 'x'}
    options = {};
    const regex = /'([^']+)'\s*:\s*('[^']*'|[^,}]+)/g;
    let match;
    while ((match = regex.exec(dictStr)) !== null) {
      let key = match[1];
      let valStr = match[2].trim();
      if (valStr.startsWith("'") && valStr.endsWith("'")) {
        valStr = valStr.slice(1, -1);
      } else if (valStr === 'None') {
        valStr = null;
      } else if (valStr === 'True') {
        valStr = true;
      } else if (valStr === 'False') {
        valStr = false;
      } else if (!isNaN(Number(valStr))) {
        valStr = Number(valStr);
      }
      options[key] = valStr;
    }
  }

  // 関数ロジック
  const sallocArgs = ['--no-shell', '-N', String(nodes), '-J', 'SmartSim'];

  // time validation (簡易的にそのまま使用)
  if (time) {
    sallocArgs.push('-t', time);
  }
  if (account) {
    sallocArgs.push('-A', String(account));
  }

  const invalid = new Set(['t', 'time', 'N', 'nodes', 'A', 'account']);
  const argumentsSet = new Set(options ? Object.keys(options) : []);
  const valid = new Set([...argumentsSet].filter(x => invalid.has(x)));
  if (valid.size > 0) {
    throw new Error(`Expecting time, nodes, account as an argument. Also received: ${[...valid].join(',')}`);
  }

  if (options) {
    for (const [opt, val] of Object.entries(options)) {
      const shortArg = opt.length === 1;
      const prefix = shortArg ? '-' : '--';
      if (!val) {
        sallocArgs.push(prefix + opt);
      } else if (shortArg) {
        sallocArgs.push(prefix + opt, String(val));
      } else {
        sallocArgs.push(prefix + opt + '=' + String(val));
      }
    }
  }

  // 出力: 要素数とスペース区切り
  console.log(sallocArgs.length);
  console.log(sallocArgs.join(' '));
});
```

