import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // data: リスト
        int nData = Integer.parseInt(br.readLine().trim());
        double[] data = new double[nData];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < nData; i++) {
            data[i] = Double.parseDouble(st.nextToken());
        }
        // n
        int n = Integer.parseInt(br.readLine().trim());
        // axis
        int axis = Integer.parseInt(br.readLine().trim());
        // xvals
        String xvals = br.readLine().trim();
        if (xvals.isEmpty()) xvals = "subsample"; // None は空文字

        double[] result = downsample(data, n, axis);
        // 出力: 要素数と要素
        System.out.println(result.length);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < result.length; i++) {
            if (i > 0) sb.append(" ");
            sb.append((long)result[i]); // 整数として出力
        }
        System.out.println(sb.toString());
    }

    public static double[] downsample(double[] data, int n, int axis) {
        // この問題ではaxis=0のみ想定
        if (n <= 1) return data;
        int nPts = data.length / n;
        double[] result = new double[nPts];
        for (int i = 0; i < nPts; i++) {
            double sum = 0;
            for (int j = 0; j < n; j++) {
                sum += data[i * n + j];
            }
            result[i] = sum / n;
        }
        return result;
    }
}
