// 簡易的なPythonリテラルパーサー
class PyValue {
public:
    enum Type { NONE, BOOL, INT, FLOAT, STRING, LIST, DICT, SET };
    Type type;
    bool bool_val;
    long long int_val;
    double float_val;
    std::string str_val;
    std::vector<PyValue> list_val;
    std::vector<std::pair<PyValue, PyValue>> dict_val;
    std::vector<PyValue> set_val;
};

// パーサー用のグローバル位置
size_t pos = 0;
std::string input;

void skip_ws() {
    while (pos < input.size() && std::isspace(input[pos])) pos++;
}

PyValue parse_value();

PyValue parse_string() {
    PyValue v;
    v.type = PyValue::STRING;
    // シングルクォートまたはダブルクォート
    char quote = input[pos];
    pos++;
    std::string result;
    while (pos < input.size() && input[pos] != quote) {
        if (input[pos] == '\\' && pos + 1 < input.size()) {
            pos++;
            switch (input[pos]) {
                case 'n': result += '\n'; break;
                case 't': result += '\t'; break;
                case 'r': result += '\r'; break;
                case '\\': result += '\\'; break;
                case '\'': result += '\''; break;
                case '"': result += '"'; break;
                default: result += input[pos];
            }
            pos++;
        } else {
            result += input[pos];
            pos++;
        }
    }
    pos++; // closing quote
    v.str_val = result;
    return v;
}

PyValue parse_number() {
    PyValue v;
    bool is_float = false;
    std::string num_str;
    while (pos < input.size() && (std::isdigit(input[pos]) || input[pos] == '.' || input[pos] == 'e' || input[pos] == 'E' || input[pos] == '+' || input[pos] == '-')) {
        if (input[pos] == '.' || input[pos] == 'e' || input[pos] == 'E') is_float = true;
        num_str += input[pos];
        pos++;
    }
    if (is_float) {
        v.type = PyValue::FLOAT;
        v.float_val = std::stod(num_str);
    } else {
        v.type = PyValue::INT;
        v.int_val = std::stoll(num_str);
    }
    return v;
}

PyValue parse_list() {
    PyValue v;
    v.type = PyValue::LIST;
    pos++; // '['
    skip_ws();
    if (pos < input.size() && input[pos] == ']') {
        pos++;
        return v;
    }
    while (true) {
        skip_ws();
        v.list_val.push_back(parse_value());
        skip_ws();
        if (pos < input.size() && input[pos] == ',') {
            pos++;
            continue;
        } else if (pos < input.size() && input[pos] == ']') {
            pos++;
            break;
        }
    }
    return v;
}

PyValue parse_dict() {
    PyValue v;
    v.type = PyValue::DICT;
    pos++; // '{'
    skip_ws();
    if (pos < input.size() && input[pos] == '}') {
        pos++;
        return v;
    }
    while (true) {
        skip_ws();
        PyValue key = parse_value();
        skip_ws();
        if (pos < input.size() && input[pos] == ':') {
            pos++;
            skip_ws();
            PyValue val = parse_value();
            v.dict_val.push_back({key, val});
        }
        skip_ws();
        if (pos < input.size() && input[pos] == ',') {
            pos++;
            continue;
        } else if (pos < input.size() && input[pos] == '}') {
            pos++;
            break;
        }
    }
    return v;
}

PyValue parse_set() {
    PyValue v;
    v.type = PyValue::SET;
    pos++; // '{'
    skip_ws();
    if (pos < input.size() && input[pos] == '}') {
        pos++;
        return v;
    }
    while (true) {
        skip_ws();
        v.set_val.push_back(parse_value());
        skip_ws();
        if (pos < input.size() && input[pos] == ',') {
            pos++;
            continue;
        } else if (pos < input.size() && input[pos] == '}') {
            pos++;
            break;
        }
    }
    return v;
}

PyValue parse_value() {
    skip_ws();
    if (pos >= input.size()) {
        PyValue v;
        v.type = PyValue::NONE;
        return v;
    }
    char c = input[pos];
    if (c == '\'' || c == '"') {
        return parse_string();
    }
    if (c == '[') {
        return parse_list();
    }
    if (c == '{') {
        // 辞書かセットか判定: 次の非空白文字が ':' なら辞書
        size_t save = pos;
        pos++;
        skip_ws();
        if (pos < input.size() && input[pos] == '}') {
