        skip_ws();
        if (pos < input.size() && input[pos] == ':') {
            // 辞書
            pos = save;
            return parse_dict();
        } else {
            // セット
            pos = save;
            return parse_set();
        }
    }
    if (c == 't' || c == 'f') {
        // true / false
        if (input.compare(pos, 4, "true") == 0) {
            pos += 4;
            PyValue v;
            v.type = PyValue::BOOL;
            v.bool_val = true;
            return v;
        } else if (input.compare(pos, 5, "false") == 0) {
            pos += 5;
            PyValue v;
            v.type = PyValue::BOOL;
            v.bool_val = false;
            return v;
        }
    }
    if (c == 'N') {
        if (input.compare(pos, 4, "None") == 0) {
            pos += 4;
            PyValue v;
            v.type = PyValue::NONE;
            return v;
        }
    }
    // 数値
    return parse_number();
}

// シリアライズ結果を出力
void print_serialized(const PyValue& v) {
    switch (v.type) {
        case PyValue::NONE:
            std::cout << "{'type': 'null'}";
            break;
        case PyValue::BOOL:
            std::cout << "{'type': 'boolean', 'value': " << (v.bool_val ? "true" : "false") << "}";
            break;
        case PyValue::INT:
            if (std::llabs(v.int_val) > 9007199254740991LL) {
                std::cout << "{'type': 'bigint', 'value': '" << v.int_val << "'}";
            } else {
                std::cout << "{'type': 'number', 'value': " << v.int_val << "}";
            }
            break;
        case PyValue::FLOAT:
            if (std::isnan(v.float_val)) {
                std::cout << "{'type': 'number', 'value': 'NaN'}";
            } else if (std::isinf(v.float_val)) {
                std::cout << "{'type': 'number', 'value': '" << (v.float_val > 0 ? "Infinity" : "-Infinity") << "'}";
            } else if (v.float_val == 0.0 && std::signbit(v.float_val)) {
                std::cout << "{'type': 'number', 'value': '-0'}";
            } else {
                std::cout << "{'type': 'number', 'value': " << v.float_val << "}";
            }
            break;
        case PyValue::STRING:
            std::cout << "{'type': 'string', 'value': '" << v.str_val << "'}";
            break;
        case PyValue::LIST:
            std::cout << "{'type': 'array', 'value': [";
            for (size_t i = 0; i < v.list_val.size(); ++i) {
                if (i > 0) std::cout << ", ";
                print_serialized(v.list_val[i]);
            }
            std::cout << "]}";
            break;
        case PyValue::DICT: {
            // sharedId チェック
            bool has_shared = false;
            std::string shared_id;
            for (const auto& p : v.dict_val) {
                if (p.first.type == PyValue::STRING && p.first.str_val == "sharedId") {
                    has_shared = true;
                    if (p.second.type == PyValue::STRING) shared_id = p.second.str_val;
                }
            }
            if (has_shared) {
                std::cout << "{'type': 'sharedReference', 'sharedId': '" << shared_id << "'}";
            } else {
                std::cout << "{'type': 'object', 'value': [";
                bool first = true;
                for (const auto& p : v.dict_val) {
                    if (!first) std::cout << ", ";
                    first = false;
                    // キーが文字列ならそのまま、それ以外はシリアライズ
                    if (p.first.type == PyValue::STRING) {
                        std::cout << "'" << p.first.str_val << "'";
                    } else {
                        print_serialized(p.first);
                    }
                    std::cout << ", ";
                    print_serialized(p.second);
                }
                std::cout << "]}";
            }
            break;
        }
        case PyValue::SET:
            std::cout << "{'type': 'set', 'value': [";
            for (size_t i = 0; i < v.set_val.size(); ++i) {
                if (i > 0) std::cout << ", ";
                print_serialized(v.set_val[i]);
            }
            std::cout << "]}";
            break;
    }
}

int main() {
    // 入力を1行読み取る
    std::getline(std::cin, input);
    pos = 0;
    PyValue val = parse_value();
    print_serialized(val);
    std::cout << std::endl;
    return 0;
}
