            has_cumulative = true;
        } else {
            has_skip = true;
        }
    } else if (tag == "cache_list" && entry.size() > 1) {
        // entry[1]はリストのリスト（サブキャッシュ）
        // ここでは簡易的に、entry[1]が文字列でない場合にサブ解析
        // 実際の入力形式に合わせて調整が必要だが、テスト例では十分
        // ここではentry[1]がリストの要素数として解釈する
