    // しかし、タグは文字列なので、数値の場合はスキップされる

    bool has_skip = false;
    bool has_cumulative = false;

    // 要素を読み取る
    for (int i = 0; i < count; i++) {
        string token = getToken(in);
        if (token.empty()) continue;
        // タグ判定
        if (token == "skip") has_skip = true;
        else if (token == "deepseek_v4_pending") has_skip = true;
        else if (token == "cumulative" || token == "deepseek_v4") has_cumulative = true;
        else if (token == "deepseek_v4_delta_v1") {
            // 次のトークンがアンカー種別
            string anchor = getToken(in);
            if (anchor.empty() || anchor == "None") has_skip = true;
            else has_cumulative = true;
        } else if (token == "zaya_cca") {
            // 次の2トークンを確認
            string a = getToken(in);
            string b = getToken(in);
            if (!b.empty() && b != "None") has_cumulative = true;
            else has_skip = true;
        } else if (token == "cache_list") {
            // サブリストの要素数を読む
            string subCountToken = getToken(in);
            if (!subCountToken.empty()) {
                int subCount = stoi(subCountToken);
                for (int j = 0; j < subCount; j++) {
                    string subToken = getToken(in);
                    if (subToken == "skip") has_skip = true;
                    else if (subToken == "deepseek_v4_pending") has_skip = true;
                    else if (subToken == "cumulative" || subToken == "deepseek_v4") has_cumulative = true;
                }
            }
        }
        // その他の値は無視
    }

    bool result = has_skip && !has_cumulative;
    cout << (result ? "true" : "false") << endl;

    return 0;
}
