using System;

class Program
{
    static string ReformatRemoveUnresolvedReferences(string text)
    {
        string newText = "";
        while (text.Length > 0)
        {
            int idx = text.IndexOf('[');
            if (idx >= 0)
            {
                newText += text.Substring(0, idx);
                int idx1 = idx + 1;
                while (idx1 < text.Length && char.IsDigit(text[idx1]))
                {
                    idx1++;
                }
                if (idx1 + 1 < text.Length)
                {
                    if (text.Substring(idx1, 2) != "]_")
                    {
                        newText += text.Substring(idx, idx1 + 2 - idx);
                    }
                    if (idx1 + 2 < text.Length)
                    {
                        text = text.Substring(idx1 + 2);
                    }
                    else
                    {
                        text = "";
                    }
                }
                else
                {
                    newText += text.Substring(idx);
                    text = "";
                }
            }
            else
            {
                newText += text;
                text = "";
            }
        }
        return newText;
    }

    static void Main()
    {
        string input = Console.ReadLine();
        string result = ReformatRemoveUnresolvedReferences(input);
        Console.WriteLine(result);
    }
}
