```csharp
using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        // リストの要素数を読み取る
        int n = int.Parse(Console.ReadLine());
        List<string> values = new List<string>();
        if (n > 0)
        {
            string[] parts = Console.ReadLine().Split(' ');
            values = parts.ToList();
        }

        // max_samplesを読み取る
        int maxSamples = int.Parse(Console.ReadLine());

        // 結果を計算
        List<double> result = SampleList(values, maxSamples);

        // 出力: 要素数と要素を空白区切りで
        Console.WriteLine(result.Count);
        if (result.Count > 0)
        {
            Console.WriteLine(string.Join(" ", result.Select(x => x.ToString("0.0###############"))));
        }
    }

    static List<double> SampleList(List<string> values, int maxSamples)
    {
        int n = values.Count;
        if (n == 0)
            return new List<double>();
        if (n <= maxSamples)
            return values.Select(v => double.Parse(v)).ToList();

        List<int> indices = new List<int>();
        for (int i = 0; i < maxSamples; i++)
        {
            indices.Add((int)(i * n / (double)maxSamples));
        }

        List<double> result = new List<double>();
        foreach (int idx in indices)
        {
            result.Add(double.Parse(values[idx]));
        }
        return result;
    }
}
