実装方針: 入力形式を解析してPythonのデータ構造を再現し、再帰的に処理して同等の出力を生成します。

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

class Program
{
    static void Main()
    {
        string input = Console.In.ReadToEnd().TrimEnd('\n');
        var lines = input.Split('\n').ToList();
        int idx = 0;
        object content = ParseValue(lines, ref idx);
        string result = ExtractContent(content, null);
        Console.WriteLine(result);
    }

    static object ParseValue(List<string> lines, ref int idx)
    {
        if (idx >= lines.Count) return "";
        string line = lines[idx];
        if (line == "true") { idx++; return true; }
        if (line == "false") { idx++; return false; }
        if (line == "None") { idx++; return null; }
        if (line == "") { idx++; return ""; }
        if (line.StartsWith("["))
        {
            // list: first line is count, next line is elements space-separated
            idx++;
            int count = int.Parse(lines[idx]);
            idx++;
            var list = new List<object>();
            if (count > 0 && idx < lines.Count)
            {
                string elementsLine = lines[idx];
                idx++;
                var elements = elementsLine.Split(' ');
                foreach (var e in elements)
                {
                    if (e == "True") list.Add(true);
                    else if (e == "False") list.Add(false);
                    else if (e == "None") list.Add(null);
                    else if (e.StartsWith("'") && e.EndsWith("'")) list.Add(e.Substring(1, e.Length - 2));
                    else if (e.StartsWith("\"") && e.EndsWith("\"")) list.Add(e.Substring(1, e.Length - 2));
                    else if (int.TryParse(e, out int intVal)) list.Add(intVal);
                    else if (double.TryParse(e, out double dblVal)) list.Add(dblVal);
                    else list.Add(e);
                }
            }
            return list;
        }
        if (line.StartsWith("{"))
        {
            // dict: parse as Python dict literal
            idx++;
            var dict = new Dictionary<string, object>();
            // Simplified: assume dict is on one line
            string dictStr = line;
            // Remove outer braces
            dictStr = dictStr.Substring(1, dictStr.Length - 2);
            if (!string.IsNullOrWhiteSpace(dictStr))
            {
                var parts = SplitTopLevel(dictStr);
                foreach (var part in parts)
                {
                    var kv = SplitKeyValue(part);
                    string key = kv.Key;
                    string valStr = kv.Value;
                    object val = ParseInlineValue(valStr);
                    dict[key] = val;
                }
            }
            return dict;
        }
        // plain string
        idx++;
        return line;
    }

    static List<string> SplitTopLevel(string s)
    {
        var result = new List<string>();
        int depth = 0;
        var current = new StringBuilder();
        foreach (char c in s)
        {
            if (c == '{' || c == '[') depth++;
            else if (c == '}' || c == ']') depth--;
            if (c == ',' && depth == 0)
            {
                result.Add(current.ToString().Trim());
                current.Clear();
            }
            else
            {
                current.Append(c);
            }
        }
        if (current.Length > 0) result.Add(current.ToString().Trim());
        return result;
    }

    static KeyValuePair<string, string> SplitKeyValue(string s)
    {
        int colonIdx = -1;
        int depth = 0;
        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];
            if (c == '{' || c == '[') depth++;
            else if (c == '}' || c == ']') depth--;
            if (c == ':' && depth == 0)
            {
                colonIdx = i;
                break;
            }
        }
        string key = s.Substring(0, colonIdx).Trim();
        string val = s.Substring(colonIdx + 1).Trim();
        if (key.StartsWith("'") && key.EndsWith("'")) key = key.Substring(1, key.Length - 2);
        else if (key.StartsWith("\"") && key.EndsWith("\"")) key = key.Substring(1, key.Length - 2);
        return new KeyValuePair<string, string>(key, val);
    }

    static object ParseInlineValue(string s)
    {
        if (s == "True") return true;
        if (s == "False") return false;
        if (s == "None") return null;
        if (s.StartsWith("'") && s.EndsWith("'")) return s.Substring(1, s.Length - 2);
        if (s.StartsWith("\"") && s.EndsWith("\"")) return s.Substring(1, s.Length - 2);
        if (s.StartsWith("["))
        {
            // inline list
            var inner = s.Substring(1, s.Length - 2);
            var items = new List<object>();
            if (!string.IsNullOrWhiteSpace(inner))
            {
                var parts = SplitTopLevel(inner);
                foreach (var p in parts)
                {
                    items.Add(ParseInlineValue(p.Trim()));
                }
            }
            return items;
        }
        if (s.StartsWith("{"))
        {
            // inline dict
            var dict = new Dictionary<string, object>();
            var inner = s.Substring(1, s.Length - 2);
            if (!string.IsNullOrWhiteSpace(inner))
            {
                var parts = SplitTopLevel(inner);
                foreach (var p in parts)
                {
                    var kv = SplitKeyValue(p);
                    dict[kv.Key] = ParseInlineValue(kv.Value);
                }
            }
            return dict;
        }
        if (int.TryParse(s, out int intVal)) return intVal;
        if (double.TryParse(s, out double dblVal)) return dblVal;
        return s;
    }

    static string ExtractContent(object content, Dictionary<string, string> toolUseMap)
    {
        if (content is string str)
        {
            return str.Trim();
        }
        if (content is List<object> list)
        {
            var parts = new List<string>();
            foreach (var item in list)
            {
                if (item is string s)
                {
                    parts.Add(s);
                }
                else if (item is Dictionary<string, object> dict)
                {
                    string blockType = dict.ContainsKey("type") ? dict["type"]?.ToString() : "";
                    if (blockType == "text")
                    {
                        parts.Add(dict.ContainsKey("text") ? dict["text"]?.ToString() ?? "" : "");
                    }
                    else if (blockType == "tool_use")
                    {
                        parts.Add(FormatToolUse(dict));
                    }
                    else if (blockType == "tool_result")
                    {
                        string tid = dict.ContainsKey("tool_use_id") ? dict["tool_use_id"]?.ToString() ?? "" : "";
                        string tname = "Unknown";
                        if (toolUseMap != null && toolUseMap.ContainsKey(tid)) tname = toolUseMap[tid];
                        object resultContent = dict.ContainsKey("content") ? dict["content"] : "";
                        string formatted = FormatToolResult(resultContent, tname);
                        if (!string.IsNullOrEmpty(formatted)) parts.Add(formatted);
                    }
                }
            }
            return string.Join("\n", parts.Where(p => !string.IsNullOrEmpty(p))).Trim();
        }
        if (content is Dictionary<string, object> dict2)
        {
            return (dict2.ContainsKey("text") ? dict2["text"]?.ToString() ?? "" : "").Trim();
        }
        return "";
    }

    static string FormatToolUse(Dictionary<string, object> dict)
    {
        // Simplified: just return a representation
        var sb = new StringBuilder();
        sb.Append("tool_use:");
        if (dict.ContainsKey("id")) sb.Append(dict["id"]);
        if (dict.ContainsKey("name")) sb.Append(" name=").Append(dict["name"]);
        if (dict.ContainsKey("input")) sb.Append(" input=").Append(dict["input"]);
        return sb.ToString();
    }

    static string FormatToolResult(object resultContent, string toolName)
    {
        if (resultContent is string s) return s;
        if (resultContent is List<object> list)
        {
            var parts = new List<string>();
            foreach (var item in list)
            {
                if (item is string str) parts.Add(str);
                else if (item is Dictionary<string, object> dict)
                {
                    if (dict.ContainsKey("type") && dict["type"]?.ToString() == "text")
                        parts.Add(dict.ContainsKey("text") ? dict["text"]?.ToString() ?? "" : "");
                }
            }
            return string.Join("\n", parts);
        }
        if (resultContent is Dictionary<string, object> dict)
        {
            return dict.ContainsKey("text") ? dict["text"]?.ToString() ?? "" : "";
        }
        return "";
    }
}
