```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func isRetryable(exc string) bool {
	// 例外名とモジュールを分離する
	// 入力は "TimeoutError" や "httpx.ConnectError" のような形式
	module := ""
	name := exc
	if idx := strings.LastIndex(exc, "."); idx != -1 {
		module = exc[:idx]
		name = exc[idx+1:]
	}

	// 組み込み例外のチェック
	if name == "TimeoutError" || name == "ConnectionError" {
		return true
	}

	// httpx モジュールのチェック
	if module == "httpx" {
		switch name {
		case "ConnectError", "ReadError", "WriteError", "TimeoutException", "NetworkError":
			return true
		}
	}

	// openai モジュールのチェック
	if module == "openai" {
		switch name {
		case "RateLimitError", "InternalServerError", "APITimeoutError", "APIConnectionError":
			return true
		}
	}

	return false
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	input := scanner.Text()

	result := isRetryable(input)
	fmt.Println(result)
}
