```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	elementStr := scanner.Text()
	element, _ := strconv.Atoi(elementStr)

	scanner.Scan()
	modulusStr := scanner.Text()
	modulus, _ := strconv.Atoi(modulusStr)

	scanner.Scan()
	phiMStr := scanner.Text()
	phiM, _ := strconv.Atoi(phiMStr)

	// 辞書の読み取り: 形式は "要素数" の行、次に "key:value key:value ..." の行
	scanner.Scan()
	countStr := scanner.Text()
	count, _ := strconv.Atoi(countStr)

	phiMDecomp := make(map[int]int)
	if count > 0 {
		scanner.Scan()
		line := scanner.Text()
		parts := strings.Fields(line)
		for _, part := range parts {
			kv := strings.Split(part, ":")
			key, _ := strconv.Atoi(kv[0])
			val, _ := strconv.Atoi(kv[1])
			phiMDecomp[key] = val
		}
	}

	result := elementOrder(element, modulus, phiM, phiMDecomp)

	// 出力: None は空行
	if result == nil {
		fmt.Println()
	} else {
		fmt.Println(*result)
	}
}

func elementOrder(element, modulus, phiM int, phiMDecomp map[int]int) *int {
	if element == 1 {
		one := 1
		return &one
	}

	// べき乗計算 (mod)
	powMod := func(base, exp, mod int) int {
		result := 1
		base = base % mod
		for exp > 0 {
			if exp%2 == 1 {
				result = (result * base) % mod
			}
			exp = exp >> 1
			base = (base * base) % mod
		}
		return result
	}

	if powMod(element, phiM, modulus) != 1 {
		return nil
	}

	order := phiM
	// 辞書の順序は不定だが、アルゴリズム上は順序に依存しない
	for factor, power := range phiMDecomp {
		for p := 1; p <= power; p++ {
			nextOrder := order / factor
			if powMod(element, nextOrder, modulus) == 1 {
				order = nextOrder
			} else {
				break
			}
		}
	}
	return &order
}
