```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func degminsec2deg(input string, back string) string {
	val := 0.0
	if strings.Contains(input, ":") {
		numlist := strings.Split(input, ":")
		for idx, ele := range numlist {
			f, err := strconv.ParseFloat(ele, 64)
			if err != nil {
				val = 999.0
				break
			}
			val += f / pow(60.0, idx)
		}
	} else {
		if strings.Contains(input, ",") {
			input = strings.Replace(input, ",", ".", -1)
		}
		f, err := strconv.ParseFloat(input, 64)
		if err != nil {
			val = 999.0
		} else {
			val = f
		}
	}

	if !(val >= -180 && val <= 360) {
		return "999.0"
	}

	if back == "minsec" {
		return decdeg2dms(val)
	}
	return strconv.FormatFloat(val, 'f', -1, 64)
}

func pow(base float64, exp int) float64 {
	result := 1.0
	for i := 0; i < exp; i++ {
		result *= base
	}
	return result
}

func decdeg2dms(dd float64) string {
	isPositive := dd >= 0
	if dd < 0 {
		dd = -dd
	}
	totalSeconds := dd * 3600
	minutes := int(totalSeconds / 60)
	seconds := totalSeconds - float64(minutes*60)
	degrees := minutes / 60
	minutes = minutes % 60
	if !isPositive {
		degrees = -degrees
	}
	return fmt.Sprintf("%d:%d:%f", degrees, minutes, seconds)
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	input := scanner.Text()
	scanner.Scan()
	back := scanner.Text()

	result := degminsec2deg(input, back)
	fmt.Println(result)
}
