```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func intToBits(i int, width *int) []int {
	w := 0
	if width != nil {
		w = *width
	}
	// 2進数文字列を生成
	binaryStr := strconv.FormatInt(int64(i), 2)
	if w > len(binaryStr) {
		binaryStr = strings.Repeat("0", w-len(binaryStr)) + binaryStr
	}
	// LSB順に反転
	bits := make([]int, len(binaryStr))
	for j, ch := range binaryStr {
		bits[len(binaryStr)-1-j] = int(ch - '0')
	}
	return bits
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	iStr := scanner.Text()
	i, _ := strconv.Atoi(iStr)

	var width *int
	if scanner.Scan() {
		wStr := scanner.Text()
		if wStr != "" {
			w, _ := strconv.Atoi(wStr)
			width = &w
		}
	}

	result := intToBits(i, width)

	// 出力: 要素数と要素
	fmt.Println(len(result))
	for _, b := range result {
		fmt.Print(b, " ")
	}
	fmt.Println()
}
