```rust
use std::collections::HashMap;
use std::io::{self, BufRead};
use std::fs::File;

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    // ファイルパスを読み取る
    let path = lines.next().unwrap().unwrap();

    // ファイルを開く
    let file = File::open(&path).unwrap();
    let reader = io::BufReader::new(file);

    let mut trnas: HashMap<String, Vec<String>> = HashMap::new();

    for line in reader.lines() {
        let line = line.unwrap();
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 7 {
            continue;
        }

        let feat_type = parts[2];
        if feat_type == "tRNA" {
            let trna_start = parts[3].to_string();
            let trna_strand = parts[6].to_string();
            let feat_info = parts[parts.len() - 1].trim();

            // gene_id=... を検索
            if let Some(pos) = feat_info.find("gene_id=") {
                let rest = &feat_info[pos..];
                let gene_id = rest.split('=').nth(1).unwrap_or("").to_string();
                trnas.insert(gene_id, vec![trna_start, trna_strand]);
            }
        }
    }

    // 出力
    if trnas.is_empty() {
        println!();
    } else {
        // 辞書をPython形式で出力
        let mut entries: Vec<(&String, &Vec<String>)> = trnas.iter().collect();
        entries.sort_by(|a, b| a.0.cmp(b.0));

        let mut result = String::from("{");
        for (i, (key, val)) in entries.iter().enumerate() {
            if i > 0 {
                result.push_str(", ");
            }
