use std::collections::HashMap;
use regex::Regex;

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    // 1行目: 要素数（無視）
    let _ = lines.next();
    // 2行目: リスト（無視）
    let _ = lines.next();
    // 3行目: 属性文字列
    let text = lines.next().unwrap().unwrap();

    let result = parse_attributes(&text);
    println!("{:?}", result);
}

fn parse_attributes(text: &str) -> HashMap<String, String> {
    let mut attributes = HashMap::new();
    let text = text.trim();

    // 区切り文字を判定
    let sep = text.chars().find(|c| *c == '=' || *c == ' ').unwrap_or(' ');

    // URLデコード
    let decoded = text
        .replace("%09", "\t")
        .replace("%0A", "\n")
        .replace("%0D", "\r")
        .replace("%25", "%")
        .replace("%3D", "=")
        .replace("%26", "&")
        .replace("%2C", ",")
        .replace("%28", "(")
        .replace("%29", ")");

    // 正規表現でパース
    let pattern = Regex::new(r"(\S+?)[= ](\".*?\"|[^;]*)(?:;|$)").unwrap();
    for cap in pattern.captures_iter(&decoded) {
        let key = cap[1].to_string();
        let mut value = cap[2].to_string();
        if value.starts_with('"') && value.ends_with('"') && value.len() >= 2 {
            value = value[1..value.len()-1].to_string();
        }
        attributes.insert(key, value);
    }

    attributes
}
