```rust
use std::io::{self, BufRead};
use std::collections::HashMap;

fn parse_value(line: &str) -> String {
    line.to_string()
}

fn parse_list(lines: &mut std::iter::Peekable<std::io::Lines<io::StdinLock>>) -> Vec<String> {
    let count_line = lines.next().unwrap().unwrap();
    let count: usize = count_line.trim().parse().unwrap_or(0);
    let mut items = Vec::new();
    if count > 0 {
        let items_line = lines.next().unwrap().unwrap();
        items = items_line.split_whitespace().map(|s| s.to_string()).collect();
        // もし空白区切りで足りない場合、追加で読む（通常は1行に収まる）
        while items.len() < count {
            let extra = lines.next().unwrap().unwrap();
            items.extend(extra.split_whitespace().map(|s| s.to_string()));
        }
    }
    items
}

fn parse_dict(s: &str) -> HashMap<String, String> {
    // 簡易パーサー: {'key': value, ...} 形式
    let mut map = HashMap::new();
    let trimmed = s.trim();
    if trimmed.len() < 2 || !trimmed.starts_with('{') || !trimmed.ends_with('}') {
        return map;
    }
    let inner = &trimmed[1..trimmed.len()-1];
    if inner.trim().is_empty() {
        return map;
    }
    // カンマで分割（ただし引用符内は考慮しない簡易版）
    let parts: Vec<&str> = inner.split(',').collect();
    for part in parts {
        let part = part.trim();
        if let Some(eq_idx) = part.find(':') {
            let key = part[..eq_idx].trim().trim_matches('\'').to_string();
            let value = part[eq_idx+1..].trim().to_string();
            map.insert(key, value);
        }
    }
    map
}

