    let mut list = Vec::new();
    if n > 0 {
        let line = lines.next().unwrap();
        let parts: Vec<&str> = line.split_whitespace().collect();
        for part in parts {
            list.push(part.to_string());
        }
    }
    list
}

fn parse_dict(lines: &mut std::str::Lines) -> HashMap<String, String> {
    let line = lines.next().unwrap();
    // 辞書はPython表記 {'a': 1} のまま文字列として扱う
    let mut map = HashMap::new();
    // 簡易パース: キーと値を抽出
    let trimmed = line.trim();
    if trimmed.len() > 2 {
        let inner = &trimmed[1..trimmed.len()-1];
        if !inner.is_empty() {
            for pair in inner.split(", ") {
                let mut parts = pair.splitn(2, ": ");
                let key = parts.next().unwrap().trim().trim_matches('\'').to_string();
                let value = parts.next().unwrap().trim().to_string();
                map.insert(key, value);
            }
        }
    }
    map
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let mut input = String::new();
    for line in lines {
        input.push_str(&line.unwrap());
        input.push('\n');
    }
    let mut lines_iter = input.lines();

    // 最初の行で型を判定
    let first_line = lines_iter.next().unwrap();
    let result: String;
    if first_line == "true" || first_line == "false" {
        result = first_line.to_string();
    } else if first_line == "None" {
        result = String::new();
    } else if first_line == "list" {
        let list = parse_list(&mut lines_iter);
        // リストの場合は要素数と要素を出力
        result = format!("{}\n{}", list.len(), list.join(" "));
    } else if first_line == "dict" {
        let dict = parse_dict(&mut lines_iter);
        // 辞書の場合はキーと値のペアを出力（ここでは元の文字列表現を返す）
        // 実際の_itemsはイテレータを返すが、Rustでは表現が難しいため、辞書の内容を文字列で返す
        let mut pairs = Vec::new();
        for (k, v) in &dict {
            pairs.push(format!("'{}': {}", k, v));
        }
        result = format!("{{{}}}", pairs.join(", "));
    } else {
        // 数値や文字列など
        result = first_line.to_string();
    }

    println!("{}", result);
}
